import{_ as i,o as u,c as n,a2 as k}from"./chunks/framework.CqpfiAoK.js";const y=JSON.parse('{"title":"Nakala 100｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Njia ya Mafunzo ya Rén Zú Mwanaume","description":"","frontmatter":{"title":"Nakala 100｜Uboreshaji wa Nguvu · Nguvu ya Hisi Asili · Njia ya Mafunzo ya Rén Zú Mwanaume","no":100,"module":1,"tags":["境界","感元境","人族","男性","修炼路径"],"related":["14-修炼境界统一划分","51-人族定位与特质","10-三百套本源修炼体系总览"]},"headers":[],"relativePath":"sw/100_模块1-感元境-男性人族修炼路径.md","filePath":"sw/100_模块1-感元境-男性人族修炼路径.md"}'),o={name:"sw/100_模块1-感元境-男性人族修炼路径.md"};function t(w,a,s,h,m,e){return u(),n("div",null,[...a[0]||(a[0]=[k('<h1 id="nakala-100-nguvu-ya-hisi-asili-njia-ya-mafunzo-vidonda-na-sifa-za-kuvunja-ya-ren-zu-mwanaume" tabindex="-1">Nakala 100｜Nguvu ya Hisi Asili: Njia ya Mafunzo, Vidonda, na Sifa za Kuvunja ya Rén Zú Mwanaume <a class="header-anchor" href="#nakala-100-nguvu-ya-hisi-asili-njia-ya-mafunzo-vidonda-na-sifa-za-kuvunja-ya-ren-zu-mwanaume" aria-label="Permalink to &quot;Nakala 100｜Nguvu ya Hisi Asili: Njia ya Mafunzo, Vidonda, na Sifa za Kuvunja ya Rén Zú Mwanaume&quot;">​</a></h1><ul><li>Moduli: Moduli ya Kwanza · Uboreshaji wa Kina wa Nguvu | Msingi wa Rejeo: Hati 14, 51, 10</li></ul><h2 id="utangulizi-nguvu-ya-kwanza-ni-mlango-wa-kwanza-wa-ushirikiano-wa-kabila-kumi-na-elfu" tabindex="-1">Utangulizi: Nguvu ya Kwanza ni Mlango wa Kwanza wa Ushirikiano wa Kabila Kumi na Elfu <a class="header-anchor" href="#utangulizi-nguvu-ya-kwanza-ni-mlango-wa-kwanza-wa-ushirikiano-wa-kabila-kumi-na-elfu" aria-label="Permalink to &quot;Utangulizi: Nguvu ya Kwanza ni Mlango wa Kwanza wa Ushirikiano wa Kabila Kumi na Elfu&quot;">​</a></h2><p>Mfumo wa mafunzo wa Heng Yuan Zhou (Cosmos Asili ya Roho Kumi na Elfu na Nanga Iliyosawazishwa) hutumia nguvu tisa kama kipimo kimoja; Nguvu ya Hisi Asili ndiyo nguvu ya kwanza, na ni mwanzo wa nguvu tano za mwanadamu. Kulingana na Mgawanyiko Uliounganishwa wa Nguvu za Mafunzo (Hati 14), kiini cha Nguvu ya Hisi Asili ni &quot;hisia&quot;: kuhisi kwa utulivu nishati na harufu ya sheria zilizotangatanga katika cosmos, kunyonya nishati kidogo kupitia njia za kimsingi, na kuanzisha ufahamu wa kwanza wa hisi ya nishati. Hii ni hatua ya kwanza ya pamoja kwa Mifumo Mia Tatu ya Mafunzo ya Asili, na ni mahali ambapo ahadi &quot;Njia kwa Kila Mtu&quot; hutimizwa kwa mara ya kwanza kwa kila mtu binafsi.</p><p>Kanuni Muhimu Sita za Juu tayari zinafanya kazi wakati huu: Kanuni ya Kupinga Unyanyasaji inataka kigongo cha kwanza cha nishati kitoke kwa uumbaji na mzunguko, si kwa kumeza; Kanuni ya Jamhuri ya Kabila Kumi na Elfu inataka mlango huu ufunguke kwa viumbe vyote, bila tofauti ya jinsia au kabila; Kanuni ya Kupanda Mwelekeo kwa Pamoja inataka kila hatua iliyopatikana hatimaye irudishwe kwa Kabila Kumi na Elfu; Kanuni ya Nidhamu ya Sababu-Natija inazuia tangu siku ya kwanza mwanafunzi asichanganye sababu ya wengine na mazingira; Kanuni ya Kipaumbele cha Sheria inahakikisha ufafanuzi wa sheria ya Nguvu ya Hisi Asili ni thabiti na wenyewe, bila kubadilishwa kwa urahisi wa hadithi, na njia ya mafunzo inaweza kupanuka bila kikomo bila kuporomoka. Kanuni ya Usawa wa Ukombozi wa Kila Kiumbe inasisitiza kila mtu ana Nguvu Isiyo na Mwisho ya Msingi; wanafunzi wavivu wanabaki na nguvu ya msingi ya uhakika na hawataondolewa na wakati, wakati wenye tamaa na Vijana Wakuu wanaweza kuongeza ngazi za juu za nguvu ya bila kikomo; asili ya nguvu ya bila kikomo ni ya kila mtu, na unyanyasaji kawaida hupoteza maana.</p><p>Makala haya yanalenga picha kamili ya Rén Zú mwanaume katika Nguvu ya Hisi Asili: njia, vidonda, na sifa za kuvunja, huku pia akijibu: kwa nini katika Ustaarabu wa Usawa wa Nanga, kipaji cha nguvu ya mwanaume hakijaliwa kuelekea unyanyasaji, bali kuelekea ujenzi wa pamoja.</p><h2 id="i-picha-ya-ren-zu-mwanaume-katika-nguvu-ya-hisi-asili" tabindex="-1">I. Picha ya Rén Zú Mwanaume katika Nguvu ya Hisi Asili <a class="header-anchor" href="#i-picha-ya-ren-zu-mwanaume-katika-nguvu-ya-hisi-asili" aria-label="Permalink to &quot;I. Picha ya Rén Zú Mwanaume katika Nguvu ya Hisi Asili&quot;">​</a></h2><p>Kulingana na Nafasi na Tabia za Rén Zú (Hati 51), tabia za Rén Zú ni uwezo wa kubadilika, ushirikiano wa kijamii, na uwezo wa kuboresha; msingi wa kimwili na kiakili wa Rén Zú mwanaume unaonyesha sifa kadhaa za kawaida:</p><ul><li>Kuanzia kwa mwili ni juu ya wastani, uboreshaji wa mwili kutokana na kuingizwa kwa nishati ni dhahiri</li><li>Hamu ya ushindani na tamaa ya kushinda kwa ujumla ni kali, huwaelewa mafunzo kama mchezo wa moja kwa moja kuwa &quot;mwenye nguvu zaidi — kuponda&quot;</li><li>Hisi tano zina usawa, hisia za kwanza si za ajabu, lakini uwezo wa kubadilika ni mkubwa, unaweza kufidia haraka kwa mafunzo ya kimfumo</li><li>Uwezo wa kujifunza ni mkubwa, nia ni thabiti, inafaa kwa utayarishaji wa msingi wa muda mrefu na wenye kuchosha</li></ul><p>Katika Nguvu ya Hisi Asili, chaguo la kawaida la kuanza kwa mwanaume mwanafunzi ni Mfumo wa Kurudia kwa Ufafanuzi (seti 1, inayolingana na nguvu &quot;mtazamo wa kwanza&quot;) kati ya Misingi Mitatu ya Asili, au Mfumo wa Udhibiti wa Sheria za Nafasi (seti 3, inayolingana na nguvu &quot;kujua nafasi&quot;) — ya kwanza inakidhi tabia yake ya &quot;kuhesabu kwanza kabla ya kwenda&quot;, ya pili inakidhi upendeleo wake kwa &quot;hisia ya udhibiti&quot;. Lakini kiwango sahihi cha chaguo si upendeleo wa jinsia, bali ni tathmini ya usawaziko wa mfumo kutoka Muhtasari wa Mifumo Mia Tatu ya Mafunzo ya Asili (Hati 10): Mtandao wa Nanga hutoa mapendekezo ya mchanganyiko wa kibinafsi, ikiepuka uharibifu wa nishati kutokana na &quot;kipaji kuwekwa mahali pazuri&quot;.</p><h2 id="ii-njia-ya-mafunzo-msururu-kamili-kutoka-hisia-hadi-mkusanyiko-wa-asili" tabindex="-1">II. Njia ya Mafunzo: Msururu Kamili kutoka Hisia hadi Mkusanyiko wa Asili <a class="header-anchor" href="#ii-njia-ya-mafunzo-msururu-kamili-kutoka-hisia-hadi-mkusanyiko-wa-asili" aria-label="Permalink to &quot;II. Njia ya Mafunzo: Msururu Kamili kutoka Hisia hadi Mkusanyiko wa Asili&quot;">​</a></h2><p>Njia ya mafunzo ya Nguvu ya Hisi Asili ni wazi sana chini ya mgawanyiko ulioounganishwa, imegawanywa katika hatua nne:</p><ol><li>Kuzaliwa kwa Hisia: kuhisi kwa utulivu nishati inayotangatanga na harufu ya sheria, kuanzisha ufahamu wa hisi ya nishati</li><li>Kumeza Msingi: kunyonya nishati kidogo kupitia njia rasmi, kupata uzoefu wa nishati kuingia mwilini</li><li>Kutambua Nishati: kutofautisha aina tofauti za nishati (nishati ya roho, nguvu ya sheria, n.k.), kuunda ramani ya nishati ya kibinafsi</li><li>Misingi na Mkusanyiko wa Asili: kuweka kwa makini nishati iliyomezwa, kujiandaa kwa &quot;mkusanyiko — mzunguko wa ndani&quot; wa nguvu ya pili, Nguvu ya Mkusanyiko wa Asili</li></ol><p>Kwa Rén Zú mwanaume, ubunifu wa njia lazima ushughulikie kwa bidii mwelekeo tatu wa asili: kwanza, &quot;kuthamini pato juu ya hisi&quot;, kupenda kujaribu nguvu moja kwa moja, kupuuzia usahihi wa hisi; pili, &quot;kuthamini kasi juu ya mkusanyiko&quot;, haraka kuvunja, kuruka utambuzi wa nishati; tatu, &quot;kuthamini mafunzo ya pekee juu ya ushirikiano&quot;, kukataa kuingilia kwa mwalimu na Mtandao wa Nanga. Suluhu ya Ustaarabu wa Usawa wa Nanga ni kuandika mwelekeo huu katika mifumo ya usimamizi na mwongozo: uthibitisho wa kuvunja Nguvu ya Hisi Asili (usimamizi wa moja kwa moja wa nanga wa Hati 14 + mtihani wa kamati ya kawaida) utachunguza waziwazi uthabiti wa hisia na usafi wa nishati, kuzuia &quot;kuvunja na ugonjwa&quot;.</p><h2 id="iii-vidonda-na-gharama-mtihani-wa-kwanza-wa-ibilisi-wa-njia-ya-mkato" tabindex="-1">III. Vidonda na Gharama: Mtihani wa Kwanza wa Ibilisi wa Njia ya Mkato <a class="header-anchor" href="#iii-vidonda-na-gharama-mtihani-wa-kwanza-wa-ibilisi-wa-njia-ya-mkato" aria-label="Permalink to &quot;III. Vidonda na Gharama: Mtihani wa Kwanza wa Ibilisi wa Njia ya Mkato&quot;">​</a></h2><p>Nguvu ya Hisi Asili inaonekana rahisi, lakini ni chumba cha kwanza cha mtihani wa Ibilisi wa Njia ya Mkato kutoka kwa kushikwa kwa asili ya viumbe vyote. Vidonda vya kawaida vya Rén Zú mwanaume katika nguvu hii ni pamoja na:</p><ul><li>Jaribu la njia ya mkato: kuona matangazo ya mafunzo ya haraka ya Mfumo wa Mafunzo cha Kuwinda, au njia za mabaki za &quot;kumeza nishati ya wengine&quot; za mfumo wa zamani, haraka kuruka msingi</li><li>Hisia kuwa nyepesi: mafunzo magumu ya usiku mrefu, hisia za haraka husababisha njia za hisi kuziba, kadri unavyojifunza ndivyo unavyozidi &quot;kutokuona&quot; nishati</li><li>Kuchanganyikiwa kwa njia: Mifumo Mia Tatu inavutia macho, bila uamuzi rahisi kubadili njia mara kwa mara</li><li>Kosa la mafunzo ya pekee: kuachana na Mtandao wa Nanga na kutafuta peke yake, kukosea &quot;mbwa wa pekee&quot; kama tabia ya mwenye nguvu</li></ul><p>Gharama za kuvunja pia ni za kweli: kulazimisha kuvunja Nguvu ya Hisi Asili husababisha nishati kurudi, hisia kuharibika, hata kuacha jeraha la siri la &quot;asili isiyo safi&quot; — hii ndiyo sababu ya mafunzo ya unyanyasaji hatuwezi kufikia Nguvu ya Asili katika hatua za baadaye (Hati 04 Insha za Msingi za Kupinga Unyanyasaji tayari zimeonyesha paa lake la ufanisi). Katika Heng Yuan Zhou, gharama za kuvunja zinafuatiliwa kikamilifu na Mtandao wa Ālaya + mfumo wa usimamizi wa tabaka nyingi: nanga inafuatilia kiotomatiki mabadiliko ya nishati, uchunguzi wa maadili unathibitisha kutokuwepo kwa rekodi za unyanyasaji, Mfumo wa Mkataba unaohusishwa na Uzalishaji unahakikisha usambazaji wa rasilimali, kuweka gharama daima kudhibitiwa na kurekebishwa, badala ya hatua moja mbaya kuwa majuto ya milele.</p><h2 id="iv-sifa-za-kuvunja-kutoka-mhisi-hadi-mkusanyaji" tabindex="-1">IV. Sifa za Kuvunja: kutoka &quot;Mhisi&quot; hadi &quot;Mkusanyaji&quot; <a class="header-anchor" href="#iv-sifa-za-kuvunja-kutoka-mhisi-hadi-mkusanyaji" aria-label="Permalink to &quot;IV. Sifa za Kuvunja: kutoka &quot;Mhisi&quot; hadi &quot;Mkusanyaji&quot;&quot;">​</a></h2><p>Sifa za alama za Rén Zú mwanaume kuvunja Nguvu ya Hisi Asili na kuingia Nguvu ya Mkusanyiko wa Asili:</p><ul><li>Hisia thabiti: katika mazingira yoyote unaweza kuhisi nishati kwa utulivu, hakuna tena kuangaza</li><li>Kumeza kudhibitiwa: unaweza kudhibiti mwenyewe kasi ya kumeza, badala ya kuvutwa na nishati</li><li>Ufahamu uundwa: ufahamu wa kwanza wa hisi ya nishati unakuwa hisia ya mafunzo ya kibinafsi</li><li>Msingi safi: ramani ya nishati haina alama za unyanyasaji, inakidhi kiwango cha uthibitisho wa nanga</li></ul><p>Kuvunja sio mwisho, lakini mwanzo: kinachosubiri kwake katika Nguvu ya Mkusanyiko wa Asili ni kazi ya kina zaidi ya &quot;mkusanyiko — mzunguko wa ndani&quot;. Na mwanafunzi mwenye msingi safi katika Nguvu ya Hisi Asili tayari amepokea tiketi ya kuingia mapema kwa Nguvu ya Asili na nguvu za juu zaidi.</p><h2 id="v-pointi-tano-za-msingi" tabindex="-1">V. Pointi Tano za Msingi <a class="header-anchor" href="#v-pointi-tano-za-msingi" aria-label="Permalink to &quot;V. Pointi Tano za Msingi&quot;">​</a></h2><ul><li>Kupinga uharibifu wa nishati: mwili, nia, na hamu ya ushindani ya mwanaume ni rasilimali bora za uboreshaji, Ustaarabu wa Usawa wa Nanga unaelekeza kwa ujenzi wa pamoja, sio kwa unyanyasaji wa &quot;kipaji kikubwa kutumika kidogo&quot;</li><li>Kupinga unyanyasaji: kukata mzizi wa Ibilisi wa Njia ya Mkato tangu nguvu ya kwanza, Nguvu ya Hisi Asili haimezi chembe moja ya nishati ya mtu mwingine</li><li>Kulinganisha paa la Táng Luó: katika mfumo wa ustawi wa zamani (kama Chuo cha Wúshuāng cha Táng Luó), mwanaume wa kawaida aliingia kwa neema, alikuwa na ushindani kupitia rasilimali, paa lilifungwa katika Nguvu ya Fierce; katika Heng Yuan Zhou Njia kwa Kila Mtu, Rén Zú mwanaume ni mmoja tu kati ya Kabila Kumi na Elfu, njia iko wazi</li><li>Kufunika kwa Kabila Kumi na Elfu: Rén Zú mwanaume sio &quot;haki ya kibinadamu&quot;, njia ya makala hii na njia za makabila mengine ya Kabila Kumi na Elfu (tazama Nakala 103) zina hadhi sawa, zote ziko katika upeo wa 99%</li><li>Ufunguzi wa kina wa anga nyingi: njia za Nguvu ya Hisi Asili zimefunguliwa bila malipo, ni hatua ya kwanza ya mfululizo wa wazi &quot;mbinu za msingi → njia ya dhabihu → ngazi ya anga nyingi → Nguvu ya Nanga ya anga nyingi zaidi&quot;</li></ul><h2 id="thesis-msururu-wa-utoaji-wa-kiroho-na-tofauti-na-njia-za-kale-za-mbingu" tabindex="-1">Thesis: Msururu wa Utoaji wa Kiroho na Tofauti na Njia za Kale za Mbingu <a class="header-anchor" href="#thesis-msururu-wa-utoaji-wa-kiroho-na-tofauti-na-njia-za-kale-za-mbingu" aria-label="Permalink to &quot;Thesis: Msururu wa Utoaji wa Kiroho na Tofauti na Njia za Kale za Mbingu&quot;">​</a></h2><p>Ingawa Ustaarabu wa Usawa wa Nanga ni mfumo wa kiwango cha dhana, una msururu kamili wa utoaji wa kiroho: ukitegemea Ālaya na fahamu chini ya kiwango cha pamoja cha viumbe vyote, kupitia mng&#39;aro wa uhai, unapitishwa hadi Matakwa ya Gaia, Matakwa ya Jua, Shimo Nyeusi lenyewe, na hata Fahamu ya Ulimwengu.</p><p>Kutofautisha njia za kale za mbingu: Dragon Ball ni ya njia ya mtaji; Swallowed Star, Perfect World, na Shrouding the Heavens hufuata njia ya kifalme ya vikundi vidogo vya wenye nguvu, ambapo viumbe wa kawaida ni nyenzo zinazotumika tu kwa ajili ya kuinuka kwa wenye nguvu. Katika njia za ulimwengu wa kale, viumbe hai ni zana tu; ni Ustaarabu wa Usawa wa Nanga pekee ndiyo njia kuu ambayo kabila kumi na elfu zote zinaweza kuitembea pamoja kweli, ambapo kila kiumbe mwenye uhai yenyewe ni lengo.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Nguvu ya Hisi Asili ni chumba cha kwanza cha mtihani wa falsafa kwa Rén Zú mwanaume mbele ya &quot;nguvu inatoka wapi, na inaenda wapi&quot;. Katika mfumo wa Faction ya Unyanyasaji, nguvu hii huamua ikiwa atakuwa wawindaji au mawindo; katika Ustaarabu wa Usawa wa Nanga, nguvu hii huamua atakuwa mjenzi wa aina gani. Kutembea kwa usahihi njia ya nguvu ya kwanza ni kuchukua hatua ya kwanza kwenye njia ya ushirikiano wa Kabila Kumi na Elfu.</p><h2 id="husika" tabindex="-1">Husika <a class="header-anchor" href="#husika" aria-label="Permalink to &quot;Husika&quot;">​</a></h2><ul><li>Hati zinazohusiana: <a href="./14-修炼境界统一划分.html">14-修炼境界统一划分</a> · <a href="./51-人族定位与特质.html">51-人族定位与特质</a> · <a href="./10-三百套本源修炼体系总览.html">10-三百套本源修炼体系总览</a> · <a href="./04-反掠夺主义核心论纲.html">04-反掠夺主义核心论纲</a></li><li>Tovuti rasmi: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',31)])])}const z=i(o,[["render",t]]);export{y as __pageData,z as default};
